// Parse scan results and categorize by severity
const scanOutput = JSON.parse($input.first().json.stdout);
const findings = scanOutput.findings || [];

const critical = findings.filter(f => f.severity === 'critical');
const high = findings.filter(f => f.severity === 'high');
const medium = findings.filter(f => f.severity === 'medium');

// Group findings by role for better reporting
const byRole = {};
findings.forEach(f => {
  const role = f.resource_name || 'unknown';
  if (!byRole[role]) byRole[role] = [];
  byRole[role].push(f);
});

return [{
  json: {
    total_findings: findings.length,
    critical_count: critical.length,
    high_count: high.length,
    medium_count: medium.length,
    roles_scanned: scanOutput.roles_scanned,
    account_id: scanOutput.account_id,
    by_role: byRole,
    top_findings: critical.concat(high).slice(0, 10),
    needs_action: critical.length > 0 || high.length > 0,
    scan_timestamp: new Date().toISOString()
  }
}];

