// Generate remediation suggestions as fixed policy JSON
const findings = $input.first().json.top_findings;
const remediations = findings.map(f => ({
  role: f.resource_name,
  rule: f.rule_id,
  severity: f.severity,
  fix: f.remediation,
  policy_name: f.policy_name || null
}));

return [{ json: { remediations, count: remediations.length } }];

